class _Operands {
  const _Operands(this.n, this.i, this.v, this.f);

  final num n;
  final int i;
  final int v;
  final int f;
}

_Operands _operandsOf(num value) {
  final absolute = value.abs();
  if (absolute == absolute.truncate()) {
    return _Operands(absolute, absolute.toInt(), 0, 0);
  }
  final parts = absolute.toString().split('.');
  return _Operands(absolute, int.parse(parts[0]), parts[1].length, int.parse(parts[1]));
}

num _operand(String name, _Operands operands) {
  return switch (name) {
    'n' => operands.n,
    'i' => operands.i,
    'v' => operands.v,
    'f' => operands.f,
    _ => throw StateError("Plural relation names operand '$name'; only n/i/v/f are supported."),
  };
}

bool _rangeMatches(num value, String text) {
  final trimmed = text.trim();
  if (trimmed.contains('..')) {
    final bounds = trimmed.split('..');
    return value >= num.parse(bounds[0]) && value <= num.parse(bounds[1]);
  }
  return value == num.parse(trimmed);
}

bool _comparisonMatches(String comparison, _Operands operands) {
  final negate = comparison.contains('!=');
  final sides = comparison.split(negate ? '!=' : '=');
  if (sides.length != 2) {
    throw StateError("Plural relation comparison '$comparison' has neither '=' nor '!='.");
  }
  final left = sides[0].trim();
  final num value;
  if (left.contains('%')) {
    final parts = left.split('%');
    value = _operand(parts[0].trim(), operands) % num.parse(parts[1].trim());
  } else {
    value = _operand(left, operands);
  }
  final matched = sides[1].split(',').any((part) => _rangeMatches(value, part));
  return matched != negate;
}

bool _relationHolds(String relation, _Operands operands) {
  return relation.split(RegExp(r'\s+or\s+')).any((conjunction) => conjunction.split(RegExp(r'\s+and\s+')).every((comparison) => _comparisonMatches(comparison.trim(), operands)));
}

const List<String> _pluralOrder = ['zero', 'one', 'two', 'few', 'many'];

/// The CLDR plural category of [value] in [locale].
String pluralCategory(num value, String locale) {
  final rules = _strings(_dataFor(locale), 'pluralRules');
  final operands = _operandsOf(value);
  for (final category in _pluralOrder) {
    final relation = rules[category];
    if (relation != null && _relationHolds(relation, operands)) {
      return category;
    }
  }
  return 'other';
}

