bool _isNegative(Object value) => value is num ? value < 0 : cruftfreeDecimalSign(value) < 0;

String _formatWithPattern(Object value, String pattern, Map<String, String> symbols, [int? fractionDigits]) => _formatShaped(pattern, symbols, fractionDigits, (digits) => (_isNegative(value), _fixedMagnitude(value, digits)));

