  final bool negative;
  final String digits;
  final int scale;
}

final RegExp _decimalAmountText = RegExp(r'^(-?)(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$');

/// The exact decimal [value] spells: a number as its shortest decimal text (what the program
/// wrote), decimal text as written -- never the binary fraction a double holds. A value that is no
/// finite number or decimal text is refused.
_DecimalAmount _decimalAmountOf(Object value) {
  final match = _decimalAmountText.firstMatch('$value');
  if (match == null) {
    throw ArgumentError('A money amount needs a finite number or decimal text; got $value.');
  }
  final fraction = match.group(3) ?? '';
  final scale = fraction.length - int.parse(match.group(4) ?? '0');
  final digits = '${match.group(2)}$fraction';
  final negative = match.group(1) == '-';
  return scale < 0 ? _DecimalAmount(negative, digits + '0' * -scale, 0) : _DecimalAmount(negative, digits, scale);
}

/// [digits] plus one, as digits.
String _incrementDigits(String digits) {
  final out = digits.split('');
  var index = out.length - 1;
  while (index >= 0 && out[index] == '9') {
    out[index] = '0';
    index--;
  }
  if (index < 0) {
    return '1${out.join()}';
  }
  out[index] = '${int.parse(out[index]) + 1}';
  return out.join();
}

/// Whether the [dropped] digits after [kept] round it up: past the half, or on it with an odd last digit.
bool _roundsUp(String kept, String dropped) {
  if (dropped[0] != '5') {
    return dropped.codeUnitAt(0) > '5'.codeUnitAt(0);
  }
  return RegExp(r'[1-9]').hasMatch(dropped.substring(1)) || int.parse(kept[kept.length - 1]).isOdd;
}

/// [amount]'s magnitude with exactly [fractionDigits] fraction digits, rounded half to even on its exact digits.
String _roundedMagnitude(_DecimalAmount amount, int fractionDigits) {
  final String digits;
  if (fractionDigits >= amount.scale) {
    digits = amount.digits + '0' * (fractionDigits - amount.scale);
  } else {
    final dropped = amount.scale - fractionDigits;
    final shifted = amount.digits.padLeft(dropped + 1, '0');
    final kept = shifted.substring(0, shifted.length - dropped);
    digits = _roundsUp(kept, shifted.substring(shifted.length - dropped)) ? _incrementDigits(kept) : kept;
  }
  final padded = digits.padLeft(fractionDigits + 1, '0');
  final whole = padded.substring(0, padded.length - fractionDigits).replaceFirst(RegExp(r'^0+(?=\d)'), '');
  return fractionDigits == 0 ? whole : '$whole.${padded.substring(padded.length - fractionDigits)}';
}

/// [amount] through [pattern] with exactly [fractionDigits] digits; a negative amount that rounds to zero has no sign.
String _formatAmount(_DecimalAmount amount, String pattern, Map<String, String> symbols, int fractionDigits) => _formatShaped(pattern, symbols, fractionDigits, (digits) {
  final fixed = _roundedMagnitude(amount, digits);
  return (amount.negative && RegExp(r'[1-9]').hasMatch(fixed), fixed);
