/// [fractionDigits] of the formatter [member], refused unless it is 0 or more.
int _requireFractionDigits(String member, int fractionDigits) {
  if (fractionDigits < 0) {
    throw RangeError('$member needs a whole number of fraction digits, 0 or more; got $fractionDigits.');
  }
  return fractionDigits;
}

// Date/time patterns.

const String _dateTimeFields = 'yMdHhmsa';

String _pad2(int value) => value < 10 ? '0$value' : '$value';

String _applyDateTimePattern(DateTime value, String pattern, Map<String, Object?> data) {
  final out = StringBuffer();
  var index = 0;
  while (index < pattern.length) {
    final char = pattern[index];
    if (!_dateTimeFields.contains(char)) {
      out.write(char);
      index++;
      continue;
    }
    var end = index;
    while (end < pattern.length && pattern[end] == char) {
      end++;
    }
    out.write(_field(value, char, end - index, data));
    index = end;
  }
  return out.toString();
}

String _field(DateTime value, String field, int width, Map<String, Object?> data) {
  final hour12 = value.hour % 12 == 0 ? 12 : value.hour % 12;
  return switch (field) {
    'y' => width == 2 ? _pad2(value.year % 100) : '${value.year}',
    'M' when width >= 4 => _list(data, 'monthNamesWide')[value.month - 1],
    'M' when width == 3 => _list(data, 'monthNamesShort')[value.month - 1],
    'M' => width == 2 ? _pad2(value.month) : '${value.month}',
    'd' => width == 2 ? _pad2(value.day) : '${value.day}',
    'H' => width == 2 ? _pad2(value.hour) : '${value.hour}',
    'h' => width == 2 ? _pad2(hour12) : '$hour12',
    'm' => width == 2 ? _pad2(value.minute) : '${value.minute}',
    's' => width == 2 ? _pad2(value.second) : '${value.second}',
    _ => _strings(data, 'dayPeriods')[value.hour < 12 ? 'am' : 'pm']!,
  };
}

/// A `Date`/`DateTime` ISO string as a local wall-clock time.
DateTime _local(String value) => DateTime.parse(value).toLocal();

// Relative time.

/// The units a relative time is shown in, each with the whole seconds one of it lasts, smallest
/// first: the shared date and time rule every client target renders.
const List<(String, int)> relativeUnits = [('second', 1), ('minute', 60), ('hour', 3600), ('day', 86400)];

/// From this many seconds ago on, a relative time is shown as the short date.
const int relativeSpanSeconds = 604800;

/// The unit and whole amount [elapsedSeconds] is shown in as a relative time: the largest unit of
/// [relativeUnits] it has reached and the whole number of it passed (never rounded up, at least
/// one); `null` when it is shown as the short date instead -- from [relativeSpanSeconds] on, or
/// below zero (a moment after now).
(String, int)? relativeUnitAndAmount(int elapsedSeconds) {
  if (elapsedSeconds < 0 || elapsedSeconds >= relativeSpanSeconds) {
    return null;
  }
  var (unit, unitSeconds) = relativeUnits.first;
  for (final (candidate, seconds) in relativeUnits) {
    if (elapsedSeconds >= seconds) {
      (unit, unitSeconds) = (candidate, seconds);
    }
  }
  final amount = elapsedSeconds ~/ unitSeconds;
  return (unit, amount < 1 ? 1 : amount);
}

/// [value] as text in [locale], in [pattern]: `date` (medium date), `shortDate`, `time`,
/// `dateTime` (short date and time) or `relative`, counted to [now]. Analysis refuses any other
/// word, so one here is an error, never a default.
String formatDateTimeAt(DateTime value, String pattern, String locale, DateTime now) {
  switch (pattern) {
    case 'date':
      return formatMediumDate(value, locale);
    case 'shortDate':
      return formatDate(value, locale);
    case 'time':
      return formatTime(value, locale);
    case 'dateTime':
      return '${formatDate(value, locale)} ${formatTime(value, locale)}';
    case 'relative':
      final relative = relativeUnitAndAmount((now.difference(value).inMicroseconds / Duration.microsecondsPerSecond).floor());
      return relative == null ? formatDate(value, locale) : formatRelativeAmount(relative.$1, relative.$2, locale);
    default:
      throw ArgumentError.value(pattern, 'pattern', 'is no date and time pattern');
  }
}

/// [amount] of [unit] in [locale]'s plural-dispatched relative-time text.
String formatRelativeAmount(String unit, int amount, String locale) {
  final relative = _dataFor(locale)['relativeTime']! as Map<String, Object?>;
  final forms = relative[unit];
  if (forms is! Map<String, Object?>) {
    throw StateError("No relative-time forms for unit '$unit' in locale '$locale'.");
  }
  final template = forms[pluralCategory(amount, locale)] ?? forms['other'];
  return (template! as String).replaceAll('{0}', '$amount');
}

/// [value] -- a number, or an exact decimal's text -- in [locale]'s decimal pattern, or with
/// [fractionDigits] exactly that many digits after the locale's decimal separator (`Fmt.number`).
/// A negative digit count is refused.
String formatNumber(Object value, String locale, [int? fractionDigits]) {
  if (fractionDigits != null) {
    _requireFractionDigits('Fmt.number', fractionDigits);
  }
  final data = _dataFor(locale);
  return _formatWithPattern(value, _strings(data, 'numberPatterns')['decimal']!, _strings(data, 'numberSymbols'), fractionDigits);
}

/// [value] -- a number, or an exact decimal's text -- in [locale]'s currency pattern, or with
/// [fractionDigits] exactly that many digits after the decimal separator, rounded half to even on
/// the exact decimal [value] spells (`2.5` is `$2` at zero digits). A negative digit count is refused.
String formatMoney(Object value, String locale, [int? fractionDigits]) {
  final data = _dataFor(locale);
  final pattern = _strings(data, 'numberPatterns')['currency']!.split('¤').join(_strings(data, 'currency')['symbol']!);
  if (fractionDigits == null) {
    return _formatWithPattern(value, pattern, _strings(data, 'numberSymbols'));
  }
  final digits = _requireFractionDigits('Fmt.money', fractionDigits);
  return _formatAmount(_decimalAmountOf(value), pattern, _strings(data, 'numberSymbols'), digits);
}

final RegExp _symbolFirst = RegExp(r'^\p{S}', unicode: true);
final RegExp _symbolLast = RegExp(r'\p{S}$', unicode: true);

/// [pattern] with its `¤` replaced by [symbol]. CLDR's currency spacing: a symbol that is not
/// itself a symbol character (`KWD`, `FCFA`, as opposed to `$` or `€`) directly beside the digits
/// is separated from them by a no-break space.
String _withCurrencySymbol(String pattern, String symbol) {
  final noBreakSpace = String.fromCharCode(0xa0);
  final beforeDigits = RegExp(r'¤[#0]').hasMatch(pattern) && !_symbolLast.hasMatch(symbol) ? noBreakSpace : '';
  final afterDigits = RegExp(r'[#0]¤').hasMatch(pattern) && !_symbolFirst.hasMatch(symbol) ? noBreakSpace : '';
  return pattern.split('¤').join('$afterDigits$symbol$beforeDigits');
}

/// A whole number of [currency]'s minor units in [locale]'s currency pattern, with that
/// currency's symbol and its own number of fraction digits (2500 EUR is `€25.00`, 2500 JPY is
/// `¥2,500`). A code outside the ISO 4217 list is refused. With [fractionDigits] the amount shows
/// exactly that many digits instead (1100000 USD at zero is `$11,000`): fewer than the currency's own
/// round half to even on the exact amount (2550 USD at zero is `$26`, 2450 is `$24`), more pad with
/// zeros. A negative digit count is refused.
String formatMinorMoney(int minorUnits, String currency, String locale, [int? fractionDigits]) {
  final data = _dataFor(locale);
  final known = (data['currencies']! as Map<String, Object?>)[currency];
  if (known is! Map<String, Object?>) {
    throw ArgumentError("'$currency' is not an ISO 4217 currency code the formatting data carries.");
  }
  final digits = known['digits']! as int;
  final pattern = _withCurrencySymbol(_strings(data, 'numberPatterns')['currency']!, known['symbol']! as String);
  if (fractionDigits == null) {
    final amount = cruftfreeDecimalDiv(minorUnits, BigInt.from(10).pow(digits).toInt());
    return _formatWithPattern(amount, pattern, _strings(data, 'numberSymbols'), digits);
  }
  final shown = _requireFractionDigits('Fmt.minorMoney', fractionDigits);
  final whole = _decimalAmountOf(minorUnits);
  return _formatAmount(_DecimalAmount(whole.negative, whole.digits, digits), pattern, _strings(data, 'numberSymbols'), shown);
}

Map<String, Object?> _namedCurrency(String currency, String locale) {
  final known = (_dataFor(locale)['currencies']! as Map<String, Object?>)[currency];
  if (known is! Map<String, Object?>) {
    throw ArgumentError("'$currency' is not an ISO 4217 currency code the formatting data carries.");
  }
  return known;
}

/// Whether [currency] is an ISO 4217 code the formatting data carries.
bool isCurrencyCode(String currency, String locale) => (_dataFor(locale)['currencies']! as Map<String, Object?>).containsKey(currency);

/// What a money input shows for a whole number of [currency]'s minor units: the major-unit amount
/// as a person writes it -- [locale]'s decimal separator, the currency's own number of fraction
/// digits, no grouping and no symbol (2500 EUR is `25.00`, 2500 JPY is `2500`). Computed on the
/// digits of the integer, never through a floating-point division.
String minorUnitsInputText(int minorUnits, String currency, String locale) {
  final digits = _namedCurrency(currency, locale)['digits']! as int;
  final symbols = _strings(_dataFor(locale), 'numberSymbols');
  final padded = minorUnits.abs().toString().padLeft(digits + 1, '0');
  final whole = padded.substring(0, padded.length - digits);
  final fraction = padded.substring(padded.length - digits);
  final sign = minorUnits < 0 ? symbols['minusSign']! : '';
  return '$sign$whole${fraction.isEmpty ? '' : symbols['decimal']!}$fraction';
}

/// What a money input's text holds: nothing, text that is no amount, or a whole number of minor units.
sealed class MinorUnitsInput {
  const MinorUnitsInput();
}

class MinorUnitsEmpty extends MinorUnitsInput {
  const MinorUnitsEmpty();
}

class MinorUnitsInvalid extends MinorUnitsInput {
  const MinorUnitsInvalid();
}

class MinorUnitsAmount extends MinorUnitsInput {
  const MinorUnitsAmount(this.minorUnits);

  final int minorUnits;
}

final RegExp _asciiDigits = RegExp(r'^[0-9]*$');

/// The largest whole number every client target holds exactly (a web number's safe integer).
final BigInt _maxSafeMinorUnits = BigInt.from(9007199254740991);

/// The whole number of [currency]'s minor units a money input's [text] writes, read in [locale]:
/// digits, the locale's decimal separator, a leading minus sign. A grouping separator or an inner
/// space is invalid, not skipped: where one locale groups with the character another uses as its
/// decimal point (`1.5`), skipping it would read a different amount than the person wrote. An
/// amount with more fraction digits than the currency has -- a cent and a half -- is invalid,
/// never rounded.
MinorUnitsInput parseMinorUnitsInput(String text, String currency, String locale) {
  final digits = _namedCurrency(currency, locale)['digits']! as int;
  final symbols = _strings(_dataFor(locale), 'numberSymbols');
  var rest = text.trim();
  if (rest.isEmpty) {
    return const MinorUnitsEmpty();
  }
  var negative = false;
  for (final minus in [symbols['minusSign']!, '-']) {
    if (rest.startsWith(minus)) {
      negative = true;
      rest = rest.substring(minus.length);
      break;
    }
  }
  final parts = rest.split(symbols['decimal']!);
  final whole = parts[0];
  final fraction = parts.length == 2 ? parts[1] : '';
  final wellFormed = parts.length <= 2 && _asciiDigits.hasMatch(whole) && _asciiDigits.hasMatch(fraction) && whole.length + fraction.length > 0 && fraction.length <= digits;
  if (!wellFormed) {
    return const MinorUnitsInvalid();
  }
  final magnitude = BigInt.parse('$whole${fraction.padRight(digits, '0')}');
  if (magnitude > _maxSafeMinorUnits) {
    return const MinorUnitsInvalid();
  }
  return MinorUnitsAmount(negative ? -magnitude.toInt() : magnitude.toInt());
}

/// [value] -- a number, or an exact decimal's text -- in [locale]'s percent pattern.
String formatPercent(Object value, String locale) {
  final data = _dataFor(locale);
  final hundredfold = value is num ? value * 100 : cruftfreeDecimalMul(value, '100');
  return _formatWithPattern(hundredfold, _strings(data, 'numberPatterns')['percent']!, _strings(data, 'numberSymbols'));
}

String formatDate(DateTime value, String locale) {
  final data = _dataFor(locale);
  return _applyDateTimePattern(value, _strings(data, 'datePatterns')['short']!, data);
}

String formatMediumDate(DateTime value, String locale) {
  final data = _dataFor(locale);
  return _applyDateTimePattern(value, _strings(data, 'datePatterns')['medium']!, data);
}

String formatTime(DateTime value, String locale) {
  final data = _dataFor(locale);
  return _applyDateTimePattern(value, _strings(data, 'timePatterns')['short']!, data);
}

/// [value] as a `Float`, `Percentage`, `Latitude` or `Longitude` reads when it is
/// interpolated into a string or joined to one: ECMAScript's `Number::toString`, the
/// same text on every target. Dart's own text is that rule except that it appends `.0`
/// to a whole value below 1e21 in magnitude (`10.0`) and keeps the sign of zero, so a
/// whole value reads as its integer text (`10`) and `-0.0` reads `0`; every other value
/// -- a fraction, the exponent form, `NaN`, `Infinity` -- is Dart's text. The integer
/// text comes from the digits Dart wrote, never through `toInt`, which cannot hold a
/// whole value from 2^63 up.
String numberText(double value) {
  if (value == 0) {
    return '0';
  }
  final text = value.toString();
  return text.endsWith('.0') ? text.substring(0, text.length - 2) : text;
}

/// Up to two upper-case initials of [text]: the first grapheme of its first
/// and last whitespace-separated words (one word gives one initial, no words
/// give `''`). Locale-independent -- upper-casing uses no locale -- so it is
/// not part of the CLDR fixture. Never throws.
String formatInitials(String text) {
  final words = text.split(RegExp(r'\s+')).where((word) => word.isNotEmpty).toList();
  if (words.isEmpty) {
    return '';
  }
  final first = words.first.characters.first.toUpperCase();
  if (words.length == 1) {
    return first;
  }
  return first + words.last.characters.first.toUpperCase();
}

/// `Fmt.*` in the locale [_locale] names -- an app's session locale, or the
/// locale a library consumer formats in (`Fmt(() => defaultClientLocale)`).
class Fmt {
  Fmt(this._locale);

  final String Function() _locale;

  String number(Object value, [int? fractionDigits]) => formatNumber(value, _locale(), fractionDigits);

  String money(Object value, [int? fractionDigits]) => formatMoney(value, _locale(), fractionDigits);

  String minorMoney(int minorUnits, String currency, [int? fractionDigits]) => formatMinorMoney(minorUnits, currency, _locale(), fractionDigits);

  /// Whether [currency] is an ISO 4217 code the formatting data carries.
  bool knowsCurrency(String currency) => isCurrencyCode(currency, _locale());

  /// The text a money input shows for [minorUnits] of [currency].
  String minorMoneyInputText(int minorUnits, String currency) => minorUnitsInputText(minorUnits, currency, _locale());

  /// The whole number of minor units a money input's [text] writes in [currency].
  MinorUnitsInput parseMinorMoneyInput(String text, String currency) => parseMinorUnitsInput(text, currency, _locale());

  String percent(Object value) => formatPercent(value, _locale());

  String date(String value) => formatDate(_local(value), _locale());

  String time(String value) => formatTime(_local(value), _locale());

  /// [value] in [pattern] ([formatDateTimeAt]), a relative time counted to this moment.
  String dateTime(String value, [String pattern = 'dateTime']) => formatDateTimeAt(_local(value), pattern, _locale(), DateTime.now());

  String relative(String value) => dateTime(value, 'relative');

  String initials(String text) => formatInitials(text);
}
